<x-app-layout><div class="mx-auto max-w-5xl space-y-5 p-4 sm:p-6"><h1 class="text-2xl font-bold">English Pronunciation Practice</h1><p class="text-gray-600">Enter a word or sentence to see its Bangla meaning and practise British or American pronunciation.</p><div class="rounded-xl border bg-white p-4"><div class="flex flex-col gap-2 sm:flex-row"><input id="ph-query" maxlength="180" class="flex-1 rounded border p-3" placeholder="Type an English word or sentence"><button id="ph-search" class="rounded bg-blue-700 px-5 py-3 text-white">Search</button></div><p class="mt-2 text-xs text-gray-500">Only teacher-approved library translations are shown. Your text is not sent to an external translation provider.</p><p id="ph-message" class="mt-2 text-sm" aria-live="polite"></p></div><div id="ph-results" class="space-y-4"></div><div class="rounded-xl border bg-slate-50 p-4"><h2 class="font-semibold">Speaking practice</h2><div class="mt-2 flex flex-wrap gap-2"><select id="ph-dialect" class="rounded border p-2"><option value="en-GB">British English (UK)</option><option value="en-US">American English (US)</option></select><button id="ph-mic" class="rounded border bg-white px-4 py-2">🎙 Start speaking</button></div><p id="ph-heard" class="mt-2 text-sm"></p><p id="ph-score" class="text-sm font-semibold" aria-live="polite"></p><small>Browser speech recognition gives approximate speech-to-text similarity, not professional phoneme-level grading.</small></div></div>
<script>
(function(){
const q=document.getElementById('ph-query'),out=document.getElementById('ph-results'),msg=document.getElementById('ph-message');let active='';
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function speak(text,locale){if(!window.speechSynthesis){msg.textContent='Text-to-speech unavailable in this browser.';return;}const u=new SpeechSynthesisUtterance(text);u.lang=locale;u.rate=.88;const v=speechSynthesis.getVoices();u.voice=v.find(x=>x.lang.toLowerCase()===locale.toLowerCase())||v.find(x=>x.lang.toLowerCase().startsWith(locale.slice(0,2)));speechSynthesis.cancel();speechSynthesis.speak(u);}
function render(e){active=e.term;const el=document.createElement('article');el.className='rounded-xl border bg-white p-5';el.innerHTML='<h2 class="text-xl font-bold">'+esc(e.term)+'</h2><p class="mt-2 text-lg">'+esc(e.translation)+'</p><div class="mt-4 grid gap-3 sm:grid-cols-2"><div class="rounded bg-slate-50 p-3"><b>British English · UK</b><p class="my-2 font-mono">'+esc(e.uk_ipa||'IPA not added')+'</p><button data-a="uk" class="rounded border px-3 py-2">▶ Listen UK</button></div><div class="rounded bg-slate-50 p-3"><b>American English · US</b><p class="my-2 font-mono">'+esc(e.us_ipa||'IPA not added')+'</p><button data-a="us" class="rounded border px-3 py-2">▶ Listen US</button></div></div>'+(e.example?'<p class="mt-3 text-sm">Example: '+esc(e.example)+'</p>':'')+(e.notes?'<p class="mt-2 text-sm text-gray-600">'+esc(e.notes)+'</p>':'');el.querySelectorAll('button').forEach(b=>b.onclick=()=>{const a=b.dataset.a,url=a==='uk'?e.uk_audio:e.us_audio;if(url){const audio=new Audio(url);audio.play().catch(()=>speak(e.term,a==='uk'?'en-GB':'en-US'));}else speak(e.term,a==='uk'?'en-GB':'en-US');});out.appendChild(el);}
async function search(){const term=q.value.trim();if(!term){msg.textContent='Please type a word or sentence.';return;}out.replaceChildren();msg.textContent='Searching…';try{const url=new URL(@json(route('student.phonetics.search')),location.origin);url.searchParams.set('q',term);const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Search unavailable.');const data=await r.json();if(!data.results.length){msg.textContent='No approved translation found. Ask your teacher/Admin to add this phrase.';return;}msg.textContent=data.results.length+' result(s)';data.results.forEach(render);}catch(e){msg.textContent=e.message;}}
document.getElementById('ph-search').onclick=search;q.onkeydown=e=>{if(e.key==='Enter')search();};
const Speech=window.SpeechRecognition||window.webkitSpeechRecognition,mic=document.getElementById('ph-mic');if(!Speech){mic.disabled=true;mic.textContent='Speech recognition not supported';}else{const rec=new Speech();rec.lang='en-GB';document.getElementById('ph-dialect').addEventListener('change',e=>{rec.lang=e.target.value;});rec.onresult=e=>{const said=e.results[0][0].transcript;document.getElementById('ph-heard').textContent='You said: '+said;const a=active.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),b=said.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old;}}document.getElementById('ph-score').textContent='Approximate transcript similarity: '+Math.max(0,Math.round(100*(1-row[b.length]/Math.max(a.length,b.length,1))))+'%';};rec.onerror=()=>document.getElementById('ph-score').textContent='Microphone or speech recognition error.';mic.onclick=()=>{if(!active){msg.textContent='Search an item first.';return;}document.getElementById('ph-score').textContent='Listening…';rec.start();};}
})();
</script></x-app-layout>